"use client";

import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";
import { profile } from "@/data";

// A particle field that morphs between the shapes in heroShapes.ts. All four target layouts live
// in vertex attributes, so the morph, swirl, idle drift and cursor repulsion all run on the GPU.

const COUNT = 9000;
// Generated by scripts/portrait_segment.py + scripts/portrait_points.py from the About photo:
// Int16 (x, y, z, brightness) per particle, scaled by 8000 (positions) and 32767 (brightness).
const PORTRAIT_URL = "/portrait-points.bin";
const MORPH_SECONDS = 1.8;

// Deterministic PRNG so every visit renders the same field.
function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gaussian(rand: () => number) {
  return Math.sqrt(-2 * Math.log(rand() + 1e-9)) * Math.cos(2 * Math.PI * rand());
}

// Rasterise the initials on a canvas and scatter particles over the filled pixels.
function initialsShape(rand: () => number, text: string): Float32Array {
  const out = new Float32Array(COUNT * 3);
  const w = 512;
  const h = 256;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d")!;
  const family = getComputedStyle(document.documentElement).getPropertyValue("--font-display").trim() || "sans-serif";
  ctx.fillStyle = "#fff";
  ctx.font = `700 230px ${family}, sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, w / 2, h / 2 + 10);
  const data = ctx.getImageData(0, 0, w, h).data;
  const filled: number[] = [];
  for (let y = 0; y < h; y += 2) {
    for (let x = 0; x < w; x += 2) {
      if (data[(y * w + x) * 4 + 3] > 128) filled.push(x, y);
    }
  }
  const pairs = filled.length / 2 || 1;
  for (let i = 0; i < COUNT; i++) {
    const k = Math.floor(rand() * pairs) * 2;
    const x = ((filled[k] ?? w / 2) / w - 0.5) * 5.2 + (rand() - 0.5) * 0.03;
    const y = -((filled[k + 1] ?? h / 2) / h - 0.5) * 2.6 + (rand() - 0.5) * 0.03;
    out.set([x, y, (rand() - 0.5) * 0.35], i * 3);
  }
  return out;
}

function decodePortrait(buf: ArrayBuffer): { pos: Float32Array; lum: Float32Array } | null {
  const q = new Int16Array(buf);
  if (q.length !== COUNT * 4) return null;
  const pos = new Float32Array(COUNT * 3);
  const lum = new Float32Array(COUNT);
  for (let i = 0; i < COUNT; i++) {
    pos[i * 3] = q[i * 4] / 8000;
    pos[i * 3 + 1] = q[i * 4 + 1] / 8000;
    pos[i * 3 + 2] = q[i * 4 + 2] / 8000;
    lum[i] = q[i * 4 + 3] / 32767;
  }
  return { pos, lum };
}

// A planet with a tilted ring of tracked objects.
function orbitShape(rand: () => number): Float32Array {
  const out = new Float32Array(COUNT * 3);
  const golden = Math.PI * (3 - Math.sqrt(5));
  const planet = Math.floor(COUNT * 0.68);
  const tilt = new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(1.25, 0, 0.32));
  const v = new THREE.Vector3();
  for (let i = 0; i < COUNT; i++) {
    if (i < planet) {
      const y = 1 - (i / (planet - 1)) * 2;
      const r = Math.sqrt(1 - y * y);
      const t = golden * i;
      v.set(Math.cos(t) * r, y, Math.sin(t) * r).multiplyScalar(1.45);
    } else {
      const a = rand() * Math.PI * 2;
      const r = 1.95 + Math.abs(gaussian(rand)) * 0.12 + (rand() < 0.25 ? 0.28 : 0);
      v.set(Math.cos(a) * r, gaussian(rand) * 0.02, Math.sin(a) * r).applyMatrix4(tilt);
    }
    out.set([v.x, v.y, v.z], i * 3);
  }
  return out;
}

// Four fully connected layers: dense clusters for neurons, particles streaming along the weights.
function neuralShape(rand: () => number): Float32Array {
  const out = new Float32Array(COUNT * 3);
  const layers = [4, 7, 7, 3];
  const nodes = layers.map((n, li) =>
    Array.from({ length: n }, (_, ni) => new THREE.Vector3(-2.4 + li * 1.6, (ni - (n - 1) / 2) * 0.62, 0)),
  );
  const edges: [THREE.Vector3, THREE.Vector3][] = [];
  for (let l = 0; l < nodes.length - 1; l++) for (const a of nodes[l]) for (const b of nodes[l + 1]) edges.push([a, b]);
  const allNodes = nodes.flat();
  for (let i = 0; i < COUNT; i++) {
    let x: number, y: number, z: number;
    if (rand() < 0.42) {
      const n = allNodes[Math.floor(rand() * allNodes.length)];
      x = n.x + gaussian(rand) * 0.055;
      y = n.y + gaussian(rand) * 0.055;
      z = gaussian(rand) * 0.055;
    } else {
      const [a, b] = edges[Math.floor(rand() * edges.length)];
      const t = rand();
      x = a.x + (b.x - a.x) * t;
      y = a.y + (b.y - a.y) * t + gaussian(rand) * 0.008;
      z = gaussian(rand) * 0.008;
    }
    out.set([x, y, z], i * 3);
  }
  return out;
}

// Retrieval in embedding space: distinct topic clusters, a tight query point in the middle,
// and particle streams linking the query to its three nearest neighbours.
function vectorShape(rand: () => number): Float32Array {
  const out = new Float32Array(COUNT * 3);
  const centers = Array.from({ length: 7 }, (_, k) => {
    const a = (k / 7) * Math.PI * 2 + 0.4;
    const r = 1.65 + (k % 2) * 0.35;
    return new THREE.Vector3(Math.cos(a) * r * 1.15, Math.sin(a) * r * 0.75, ((k * 37) % 7) / 7 - 0.5);
  });
  const query = new THREE.Vector3(0, 0, 0.2);
  const retrieved = [...centers].sort((p, q) => p.distanceTo(query) - q.distanceTo(query)).slice(0, 3);
  for (let i = 0; i < COUNT; i++) {
    const roll = rand();
    let x: number, y: number, z: number;
    if (roll < 0.06) {
      x = query.x + gaussian(rand) * 0.06;
      y = query.y + gaussian(rand) * 0.06;
      z = query.z + gaussian(rand) * 0.06;
    } else if (roll < 0.16) {
      const target = retrieved[Math.floor(rand() * retrieved.length)];
      const t = rand();
      x = query.x + (target.x - query.x) * t + gaussian(rand) * 0.01;
      y = query.y + (target.y - query.y) * t + gaussian(rand) * 0.01;
      z = query.z + (target.z - query.z) * t;
    } else if (roll < 0.22) {
      x = (rand() - 0.5) * 4.8;
      y = (rand() - 0.5) * 3.2;
      z = (rand() - 0.5) * 1.6;
    } else {
      const c = centers[Math.floor(rand() * centers.length)];
      x = c.x + gaussian(rand) * 0.17;
      y = c.y + gaussian(rand) * 0.17;
      z = c.z + gaussian(rand) * 0.17;
    }
    out.set([x, y, z], i * 3);
  }
  return out;
}

const vertexShader = /* glsl */ `
  attribute vec3 aP0;
  attribute vec3 aP1;
  attribute vec3 aP2;
  attribute vec3 aP3;
  attribute float aRand;
  attribute float aAccent;
  attribute float aLum;
  uniform float uFrom;
  uniform float uTo;
  uniform float uProgress;
  uniform float uTime;
  uniform float uSize;
  uniform float uPixelRatio;
  uniform vec2 uMouse;
  uniform float uAspect;
  uniform float uMouseStrength;
  varying float vAccent;
  varying float vAlpha;
  varying float vBright;

  vec3 shape(float i) {
    if (i < 0.5) return aP0;
    if (i < 1.5) return aP1;
    if (i < 2.5) return aP2;
    return aP3;
  }

  void main() {
    // Stagger each particle a little so the morph ripples instead of moving in lockstep.
    float delay = aRand * 0.35;
    float t = clamp((uProgress - delay) / 0.65, 0.0, 1.0);
    t = t < 0.5 ? 4.0 * t * t * t : 1.0 - pow(-2.0 * t + 2.0, 3.0) / 2.0;

    vec3 p = mix(shape(uFrom), shape(uTo), t);
    // Swirl outward mid-flight.
    float flight = sin(t * 3.14159);
    float ang = flight * (aRand - 0.5) * 2.2;
    p.xz = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * p.xz;
    p += normalize(p + 1e-4) * flight * 0.6 * aRand;
    // Gentle idle drift.
    p += 0.02 * vec3(sin(uTime * 1.3 + aRand * 40.0), cos(uTime * 1.1 + aRand * 30.0), sin(uTime * 0.9 + aRand * 20.0));

    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    vec4 clip = projectionMatrix * mv;
    vec2 diff = clip.xy / clip.w - uMouse;
    diff.x *= uAspect;
    float force = smoothstep(0.3, 0.0, length(diff)) * uMouseStrength;
    mv.xy += normalize(diff + 1e-4) * force * 0.55;

    gl_Position = projectionMatrix * mv;
    // Shape 0 is the portrait: shade each particle by the photo's tone and calm the orange specks.
    float portrait = (uFrom < 0.5 ? 1.0 - t : 0.0) + (uTo < 0.5 ? t : 0.0);
    gl_PointSize = uSize * uPixelRatio * (0.55 + aRand * 0.9) * mix(1.0, 0.8, portrait) / -mv.z;
    vAccent = aAccent * (1.0 - 0.8 * portrait);
    vAlpha = mix(0.35 + 0.5 * aRand, 0.75 + 0.25 * aRand, portrait);
    vBright = mix(1.0, aLum, portrait);
  }
`;

const fragmentShader = /* glsl */ `
  uniform vec3 uBase;
  uniform vec3 uAccent;
  uniform float uOpacity;
  varying float vAccent;
  varying float vAlpha;
  varying float vBright;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    if (d > 0.5) discard;
    float a = smoothstep(0.5, 0.05, d) * vAlpha * uOpacity;
    // Glows brighter where the photo is lit.
    vec3 col = mix(uBase, uAccent, vAccent) * vBright;
    gl_FragColor = vec4(col, a);
  }
`;

function Particles({
  stage,
  reducedMotion,
  portrait,
}: {
  stage: number;
  reducedMotion: boolean;
  portrait: { pos: Float32Array; lum: Float32Array } | null;
}) {
  const material = useRef<THREE.ShaderMaterial>(null);
  const group = useRef<THREE.Group>(null);
  const { gl, size, invalidate } = useThree();
  const morph = useRef({ from: stage, to: stage, start: -10 });
  const mouse = useRef({ x: 10, y: 10, last: -1e9 });

  const geometry = useMemo(() => {
    const rand = mulberry32(19);
    const g = new THREE.BufferGeometry();
    // Fall back to the initials if the portrait data could not be loaded.
    const first = portrait?.pos ?? initialsShape(rand, profile.initials);
    const shapes = [first, orbitShape(rand), neuralShape(rand), vectorShape(rand)];
    shapes.forEach((s, i) => g.setAttribute(`aP${i}`, new THREE.BufferAttribute(s, 3)));
    g.setAttribute("position", new THREE.BufferAttribute(shapes[0], 3));
    const r = new Float32Array(COUNT);
    const accent = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      r[i] = rand();
      accent[i] = rand() < 0.13 ? 1 : 0;
    }
    g.setAttribute("aRand", new THREE.BufferAttribute(r, 1));
    g.setAttribute("aAccent", new THREE.BufferAttribute(accent, 1));
    g.setAttribute("aLum", new THREE.BufferAttribute(portrait?.lum ?? new Float32Array(COUNT).fill(1), 1));
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 6);
    return g;
  }, [portrait]);

  const uniforms = useMemo(
    () => ({
      uFrom: { value: 0 },
      uTo: { value: 0 },
      uProgress: { value: 1 },
      uTime: { value: 0 },
      uSize: { value: 30 },
      uPixelRatio: { value: 1 },
      uMouse: { value: new THREE.Vector2(10, 10) },
      uAspect: { value: 1 },
      uMouseStrength: { value: 0 },
      uBase: { value: new THREE.Color() },
      uAccent: { value: new THREE.Color() },
      uOpacity: { value: 1 },
    }),
    [],
  );

  useEffect(() => () => geometry.dispose(), [geometry]);

  // The canvas sits behind the hero copy, so track the pointer on the window instead of canvas events.
  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      const rect = gl.domElement.getBoundingClientRect();
      mouse.current.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.current.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      mouse.current.last = performance.now();
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => window.removeEventListener("pointermove", onMove);
  }, [gl]);

  useEffect(() => {
    if (stage === morph.current.to) return;
    morph.current = { from: morph.current.to, to: stage, start: performance.now() / 1000 };
    invalidate(); // render the new shape even when the frameloop is on demand (reduced motion)
  }, [stage, invalidate]);

  useFrame(({ clock }, dt) => {
    const m = material.current;
    if (!m) return;
    const u = m.uniforms;
    const now = performance.now() / 1000;
    u.uFrom.value = morph.current.from;
    u.uTo.value = morph.current.to;
    u.uProgress.value = reducedMotion ? 1 : Math.min(1, (now - morph.current.start) / MORPH_SECONDS);
    u.uTime.value = reducedMotion ? 0 : clock.getElapsedTime();
    u.uPixelRatio.value = gl.getPixelRatio();
    u.uAspect.value = size.width / size.height;
    u.uSize.value = size.width < 640 ? 18 : 25;
    u.uMouse.value.set(mouse.current.x, mouse.current.y);
    const pointerActive = !reducedMotion && performance.now() - mouse.current.last < 1500;
    u.uMouseStrength.value = THREE.MathUtils.damp(u.uMouseStrength.value, pointerActive ? 1 : 0, 4, dt);
    u.uBase.value.set("#d4d6de");
    u.uAccent.value.set("#ff6a2b");
    m.blending = THREE.AdditiveBlending;

    if (group.current && !reducedMotion) {
      // Sway rather than spin so the initials stay legible; lean slightly toward the pointer.
      const t = clock.getElapsedTime();
      const px = pointerActive ? THREE.MathUtils.clamp(mouse.current.x, -1, 1) : 0;
      const py = pointerActive ? THREE.MathUtils.clamp(mouse.current.y, -1, 1) : 0;
      group.current.rotation.y = THREE.MathUtils.damp(
        group.current.rotation.y,
        Math.sin(t * 0.3) * 0.35 + px * 0.15,
        2,
        dt,
      );
      group.current.rotation.x = THREE.MathUtils.damp(
        group.current.rotation.x,
        Math.cos(t * 0.25) * 0.08 - py * 0.1,
        2,
        dt,
      );
    }
  });

  return (
    <group ref={group} scale={size.width < 640 ? 0.75 : 0.82} position={[size.width < 640 ? 0 : 0.15, 0.1, 0]}>
      <points geometry={geometry} frustumCulled={false}>
        <shaderMaterial
          ref={material}
          vertexShader={vertexShader}
          fragmentShader={fragmentShader}
          uniforms={uniforms}
          transparent
          depthWrite={false}
          blending={THREE.AdditiveBlending}
        />
      </points>
    </group>
  );
}

export default function HeroScene({
  stage,
  reducedMotion,
  active,
}: {
  stage: number;
  reducedMotion: boolean;
  active: boolean;
}) {
  const [portrait, setPortrait] = useState<{ pos: Float32Array; lum: Float32Array } | null | undefined>(undefined);

  useEffect(() => {
    let cancelled = false;
    fetch(PORTRAIT_URL)
      .then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(String(r.status)))))
      .then((buf) => !cancelled && setPortrait(decodePortrait(buf)))
      .catch(() => !cancelled && setPortrait(null));
    return () => {
      cancelled = true;
    };
  }, []);

  if (portrait === undefined) return null;

  return (
    <Canvas
      camera={{ position: [0, 0, 7], fov: 45 }}
      dpr={[1, 1.75]}
      gl={{ antialias: false, alpha: true, powerPreference: "high-performance" }}
      frameloop={!active ? "never" : reducedMotion ? "demand" : "always"}
      aria-hidden
    >
      <Particles stage={stage} reducedMotion={reducedMotion} portrait={portrait} />
    </Canvas>
  );
}
